class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        n = len(circles)
        parent = list(range(n + 2))
        TL = n
        BR = n + 1

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        def seg_dist_sq(px, py, x1, y1, x2, y2):
            dx, dy = x2 - x1, y2 - y1
            L = dx * dx + dy * dy
            if L == 0:
                return (px - x1) ** 2 + (py - y1) ** 2
            t = ((px - x1) * dx + (py - y1) * dy) / L
            t = max(0.0, min(1.0, t))
            cx = x1 + t * dx
            cy = y1 + t * dy
            return (px - cx) ** 2 + (py - cy) ** 2

        for i, (x, y, r) in enumerate(circles):
            r2 = r * r
            # circle covers a corner
            if x * x + y * y <= r2 or (x - xCorner) ** 2 + (y - yCorner) ** 2 <= r2:
                return False
            # touches top-left boundary (left edge or top edge)
            d_left = seg_dist_sq(x, y, 0, 0, 0, yCorner)
            d_top = seg_dist_sq(x, y, 0, yCorner, xCorner, yCorner)
            if d_left <= r2 or d_top <= r2:
                union(i, TL)
            # touches bottom-right boundary (bottom edge or right edge)
            d_bottom = seg_dist_sq(x, y, 0, 0, xCorner, 0)
            d_right = seg_dist_sq(x, y, xCorner, 0, xCorner, yCorner)
            if d_bottom <= r2 or d_right <= r2:
                union(i, BR)

        for i in range(n):
            x1, y1, r1 = circles[i]
            for j in range(i + 1, n):
                x2, y2, r2c = circles[j]
                s = r1 + r2c
                if (x1 - x2) ** 2 + (y1 - y2) ** 2 <= s * s:
                    union(i, j)

        return find(TL) != find(BR)
