class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        # Corners inside a circle block immediately
        for x, y, r in circles:
            if x * x + y * y <= r * r:
                return False
            dx = xCorner - x
            dy = yCorner - y
            if dx * dx + dy * dy <= r * r:
                return False

        n = len(circles)
        # Nodes: 0..n-1 circles, n = LEFT, n+1 = TOP, n+2 = RIGHT, n+3 = BOTTOM
        LEFT, TOP, RIGHT, BOTTOM = n, n + 1, n + 2, n + 3
        parent = list(range(n + 4))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        for i in range(n):
            x, y, r = circles[i]
            if x <= r:
                union(i, LEFT)
            if y <= r:
                union(i, BOTTOM)
            if xCorner - x <= r:
                union(i, RIGHT)
            if yCorner - y <= r:
                union(i, TOP)
            for j in range(i + 1, n):
                x2, y2, r2 = circles[j]
                dx = x - x2
                dy = y - y2
                rs = r + r2
                if dx * dx + dy * dy <= rs * rs:
                    union(i, j)

        return find(LEFT) != find(RIGHT) and find(TOP) != find(BOTTOM) \
            and find(LEFT) != find(BOTTOM) and find(TOP) != find(RIGHT)
