        n = len(circles)
        # nodes: 0..n-1 circles, n = S (bottom/left), n+1 = E (top/right)
        parent = list(range(n + 2))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        S = n
        E = n + 1

        for i, (x, y, r) in enumerate(circles):
            # origin or destination covered
            if x * x + y * y <= r * r:
                return False
            dx = xCorner - x
            dy = yCorner - y
            if dx * dx + dy * dy <= r * r:
                return False
            if x <= r or y <= r:
                union(i, S)
            if dx <= r or dy <= r:
                union(i, E)

        for i in range(n):
            xi, yi, ri = circles[i]
            for j in range(i + 1, n):
                xj, yj, rj = circles[j]
                ddx = xi - xj
                ddy = yi - yj
                rs = ri + rj
                if ddx * ddx + ddy * ddy <= rs * rs:
                    union(i, j)

        return find(S) != find(E)
