from collections import deque

class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        def seg_dist2(px, py, ax, ay, bx, by):
            dx, dy = bx - ax, by - ay
            L2 = dx * dx + dy * dy
            t = ((px - ax) * dx + (py - ay) * dy)
            if t <= 0:
                cx, cy = ax, ay
            elif t >= L2:
                cx, cy = bx, by
            else:
                cx = ax + t * dx / L2
                cy = ay + t * dy / L2
            return (px - cx) ** 2 + (py - cy) ** 2

        def touches(x, y, r, ax, ay, bx, by):
            # exact check using integer comparison when possible
            dx, dy = bx - ax, by - ay
            L2 = dx * dx + dy * dy
            t = ((x - ax) * dx + (y - ay) * dy)
            if t <= 0:
                return (x - ax) ** 2 + (y - ay) ** 2 <= r * r
            if t >= L2:
                return (x - bx) ** 2 + (y - by) ** 2 <= r * r
            # perpendicular distance: cross^2 <= r^2 * L2
            cross = dx * (y - ay) - dy * (x - ax)
            return cross * cross <= r * r * L2

        n = len(circles)
        # corners check
        for x, y, r in circles:
            if x * x + y * y <= r * r:
                return False
            if (x - xCorner) ** 2 + (y - yCorner) ** 2 <= r * r:
                return False

        # walls: Top, Left (start side); Bottom, Right (end side)
        def start_side(x, y, r):
            return (touches(x, y, r, 0, yCorner, xCorner, yCorner) or
                    touches(x, y, r, 0, 0, 0, yCorner))

        def end_side(x, y, r):
            return (touches(x, y, r, 0, 0, xCorner, 0) or
                    touches(x, y, r, xCorner, 0, xCorner, yCorner))

        visited = [False] * n
        dq = deque()
        for i in range(n):
            if start_side(*circles[i]):
                visited[i] = True
                dq.append(i)
        while dq:
            i = dq.popleft()
            xi, yi, ri = circles[i]
            if end_side(xi, yi, ri):
                return False
            for j in range(n):
                if not visited[j]:
                    xj, yj, rj = circles[j]
                    if (xi - xj) ** 2 + (yi - yj) ** 2 <= (ri + rj) ** 2:
                        visited[j] = True
                        dq.append(j)
        return True

