def ref(inp):
    # Exact characterization by the blocking-chain argument:
    # The rectangle boundary splits into arc A (left side + top side, from
    # (0,0) to (X,Y)) and arc B (bottom side + right side). A path from
    # (0,0) to (X,Y) inside the rectangle, avoiding closed disks, exists iff
    # no chain of disks (consecutive disks intersecting as closed sets)
    # links a disk touching arc A with a disk touching arc B.
    X, Y, circles = _parse(inp)

    def clamp(v, lo, hi):
        return max(lo, min(hi, v))

    def touches_A(x, y, r):
        # left side: {0} x [0,Y]
        dy = y - clamp(y, 0, Y)
        if x * x + dy * dy <= r * r:
            return True
        # top side: [0,X] x {Y}
        dx = x - clamp(x, 0, X)
        dy2 = y - Y
        if dx * dx + dy2 * dy2 <= r * r:
            return True
        return False

    def touches_B(x, y, r):
        # bottom side: [0,X] x {0}
        dx = x - clamp(x, 0, X)
        if dx * dx + y * y <= r * r:
            return True
        # right side: {X} x [0,Y]
        dx2 = X - x
        dy = y - clamp(y, 0, Y)
        if dx2 * dx2 + dy * dy <= r * r:
            return True
        return False

    n = len(circles)
    tA = [touches_A(*c) for c in circles]
    tB = [touches_B(*c) for c in circles]

    def adjacent(i, j):
        xi, yi, ri = circles[i]
        xj, yj, rj = circles[j]
        return (xi - xj) ** 2 + (yi - yj) ** 2 <= (ri + rj) ** 2

    seen = [False] * n
    stack = []
    for i in range(n):
        if tA[i]:
            seen[i] = True
            stack.append(i)
    while stack:
        u = stack.pop()
        if tB[u]:
            return "false"
        for v in range(n):
            if not seen[v] and adjacent(u, v):
                seen[v] = True
                stack.append(v)
    return "true"
